css:
/* ----------------------------------------------------------- TESTIMONIALS ---
   Bordered white cards on the paper band. The handoff carries no star
   rating, so none is drawn. */

[data-bz-node="testimonials-band"]{padding-top:120px;padding-bottom:120px;}
[data-bz-node="testimonials-band"] .bz-block{padding-block:0;}
[data-bz-node="testimonials-heading"] h2{margin:0 0 52px;}
[data-bz-node="testimonials-grid-row"]{gap:32px;}
[data-bz-node="testimonials-grid-row"] > .bz-col{
  display:flex;flex-direction:column;
  background:var(--card);border:1px solid var(--line);padding:32px;
}
[data-bz-node="testimonials-grid-row"] .bz-text{max-width:none;}
[data-bz-node="testimonials-grid-row"] > .bz-col > .bz-block:nth-child(1) p{
  font-size:var(--text-body);line-height:1.6;color:#242424;margin:0 0 20px;
}
[data-bz-node="testimonials-grid-row"] > .bz-col > .bz-block:nth-child(2) p{
  font:700 var(--text-small)/1.6 var(--font-body);color:#242424;margin:0;
}
[data-bz-node="testimonials-grid-row"] > .bz-col > .bz-block:nth-child(3) p{
  font:400 13px/1.6 var(--font-body);color:var(--muted);margin:0;
}
@media (max-width:640px){[data-bz-node="testimonials-band"]{padding-top:64px;padding-bottom:64px;}}
